import subprocess, time, sys, re
sys.path.insert(0,'/tmp')
from helper import *
def send1(k):
    subprocess.run(["tmux","send-keys","-t","t1",k]); time.sleep(0.15)
def preview():
    out=cap("t1")
    for l in out.splitlines():
        if "log preview for" in l:
            return l.strip().strip("│").strip().replace("log preview for ","")
    return "?"
def highlighted():
    out=cap("t1",esc=True)
    results=[]
    for r,l in enumerate(out.splitlines()):
        # find sequences containing 7m
        # split by escape
        # simpler: remove esc to get plain, but need locate inverted segment: regex
        for m in re.finditer(r'\x1b\[([0-9;]*)m([^\x1b]*)', l):
            if '7' in m.group(1).split(';'):
                txt=m.group(2)
                if txt.strip():
                    # compute column in plain text: position before m start minus escapes in prefix
                    plain_prefix=re.sub(r'\x1b\[[0-9;]*m','',l[:m.start()])
                    results.append((r,len(plain_prefix),txt,m.group(1)))
    return results
def do(label, seq):
    start("t1","/workspace/executable -c /tmp/name/config.ini --log-dir-path /tmp/name/logs",160,50)
    send1("Tab"); send1("Tab")
    print(label, "start", preview(), highlighted())
    for k in seq:
        send1(k); print(" ",k, preview(), highlighted())
do("j k", ["j","k"])
do("l l k", ["l","l","k"])
