import subprocess, re, sys
sys.path.insert(0,'/tmp')
from helper import *
def get_grid():
    out=cap("t1",esc=True)
    grid=[] # list rows list (char, attrs tuple)
    for row in out.splitlines():
        cells=[]
        cur=frozenset()
        i=0
        while i < len(row):
            if row[i]=='\x1b':
                m=re.match(r'\x1b\[([0-9;]*)m',row[i:])
                if m:
                    codes=m.group(1)
                    # interpret tmux codes: 0 reset, 1 bold,2 dim,4 underline,7 reverse, 31-37 fg, 39 default, etc, also 0;... combos tmux emits
                    # tmux sequences seem cumulative? It emits e.g. \x1b[1;7m etc and \x1b[0m resets, \x1b[0;2m etc. So a parameter list: if starts 0 reset then apply rest; else add/remove?
                    parts=[int(x) if x else 0 for x in codes.split(';')] if codes else [0]
                    s=set(cur)
                    for p in parts:
                        if p==0: s=set()
                        elif p==39: 
                            # remove fg codes
                            s={x for x in s if not (30<=x<=37 or 90<=x<=97 or x>=1000)}
                        elif p==49:
                            s={x for x in s if not (40<=x<=47)}
                        elif 30<=p<=37 or 40<=p<=47 or 90<=p<=97:
                            # replace fg/bg
                            if 30<=p<=37 or 90<=p<=97: s={x for x in s if not (30<=x<=37 or 90<=x<=97)}
                            s.add(p)
                        else: s.add(p)
                    cur=frozenset(s)
                    i+=len(m.group(0)); continue
                else: i+=1; continue
            cells.append((row[i],cur))
            i+=1
        grid.append(cells)
    return grid

def show_dates(label):
    grid=get_grid()
    # print unique attr sets with example text runs
    from collections import defaultdict
    runs=defaultdict(list)
    for r,cells in enumerate(grid):
        cur=None; txt=""
        for ch,a in cells+ [(" ",None)]:
            if a!=cur:
                if txt.strip(): runs[cur].append(txt.strip())
                cur=a; txt=ch
            else: txt+=ch
        if txt.strip(): runs[cur].append(txt.strip())
    print("==",label)
    for k,v in sorted(runs.items(), key=lambda x: str(x[0])):
        print(k, v[:20])

if __name__=="__main__":
    show_dates("cur")
