# ---------------- config ptree ----------------------
class PNode:
    def __init__(self, value=''):
        self.value=value
        self.children={}  # name->PNode, insertion ordered
        self.is_section=False
    def child(self, name, create=False):
        if name not in self.children:
            if not create: return None
            self.children[name]=PNode()
        return self.children[name]
    def get_path(self, path):
        node=self
        for part in path:
            node=node.child(part)
            if node is None: return None
        return node
    def get_str(self, path, default=None):
        n=self.get_path(path)
        if n is None: return default
        return n.value
    def has(self,path): return self.get_path(path) is not None

def parse_ini_file(path):
    # Caller handles open errors
    try:
        with open(path,'rb') as f: data=f.read()
    except IsADirectoryError:
        raise AppError("basic_filebuf::underflow error reading the file: Is a directory")
    except FileNotFoundError:
        raise AppError(f"Failed to open file: {path}")
    except PermissionError:
        raise AppError(f"Failed to open file: {path}")
    except OSError as e:
        raise AppError(f"Failed to open file: {path}")
    text=data.decode('utf-8',errors='surrogateescape')
    root=PNode()
    current_path=[]
    seen_sections=set()
    seen_keys=set()  # tuple paths that are leaf explicitly
    for lineno, raw_line in enumerate(text.splitlines(),start=1):
        line=raw_line.strip()
        if not line: continue
        if line[0] in (';','#'): continue
        if line.startswith('['):
            if ']' not in line:
                raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): unmatched '['")
            end=line.find(']')
            sec=line[1:end].strip()
            if not sec:
                current_path=[]; continue
            path=tuple(sec.split('.'))
            if path in seen_sections:
                raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): duplicate section name")
            seen_sections.add(path)
            # create nodes
            node=root
            for part in path:
                node=node.child(part,create=True)
                node.is_section=True
            current_path=list(path)
            continue
        if '=' not in raw_line:
            raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): '=' character not found in line")
        key_part, value_part = raw_line.split('=',1)
        key=key_part.strip()
        value=value_part.strip()
        if not key:
            raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): key expected")
        full_path=tuple(current_path+key.split('.'))
        if full_path in seen_keys:
            raise AppError(f"Failed to parse configuration file: <unspecified file>({lineno}): duplicate key name")
        seen_keys.add(full_path)
        node=root
        for part in full_path:
            node=node.child(part,create=True)
        node.value=value
    return root

