def wrap_help_line(prefix, desc, width=80):
    # Reproduce boost style: prefix padded to col24, wrap descriptions
    indent=24
    lines=[]
    # words preserving spaces: split on single spaces (descriptions are single-spaced)
    words=desc.split(' ')
    cur=prefix.ljust(indent)
    # prefix may be > indent (log-name-format): it already is 24 exactly-ish
    if len(prefix)>=indent:
        cur=prefix
        if not cur.endswith(' '): cur+=' '
    # We'll token process
    for w in words:
        # If cur is just prefix/indent and word is too long for remaining, split it
        # line desirable max 79 chars before forcing break (trailing space counts)
        # Algorithm approximating boost: if adding word (+space) would make line >79, wrap.
        # For a fresh continuation line, if word longer than avail, split.
        while True:
            avail=79-len(cur)
            if len(w) <= avail:
                # decide wrap: if cur has textual content beyond indent and adding w plus maybe space exceeds? Boost keeps trailing space.
                # Simply add if fits within 79
                cur+=w+' '
                break
            else:
                # If cur has content beyond indent/prefix, wrap first
                stripped_len=len(cur.rstrip())
                content_len=stripped_len-indent if len(cur)>=indent else stripped_len
                has_content = stripped_len>indent if cur.startswith(' ') else stripped_len>0
                # Determine if current line already contains description words: check len beyond indent
                if len(cur.strip())>0 and cur[indent:].strip() if len(cur)>=indent else cur.strip():
                    lines.append(cur)
                    cur=' '*indent
                    continue
                # Fresh line and word too long: split to fill avail
                if avail<=0:
                    lines.append(cur); cur=' '*indent; continue
                part=w[:avail]
                cur+=part
                lines.append(cur)
                w=w[avail:]
                cur=' '*indent
                continue
    lines.append(cur.rstrip() if False else cur)  # keep trailing space? Boost last line has no trailing space for final word? Observed final desc lines end without trailing? e.g. show line no trailing in repr. First wrapped lines keep trailing space.
    # Remove trailing space from final line
    if lines:
        lines[-1]=lines[-1].rstrip()
    return lines

def print_help(default_config):
    out_lines=[]
    out_lines.append("Captain's Log (caps-log)! A CLI journalig tool.")
    out_lines.append(f"Version: {VERSION}")
    out_lines.append("Allowed options:")
    prefixes={
        'help':"  -h [ --help ]",
        'config':"  -c [ --config ] arg",
        'log-dir-path':"  --log-dir-path arg",
        'log-name-format':"  --log-name-format arg",
        'sunday-start':"  --sunday-start",
        'first-line-section':"  --first-line-section",
        'password':"  --password arg",
        'encrypt':"  --encrypt",
        'decrypt':"  --decrypt",
    }
    for spec in OPT_SPECS:
        desc=spec.desc
        if spec.long=='config':
            desc=f"override the default config file path ({default_config})"
        lines=wrap_help_line(prefixes[spec.long],desc)
        out_lines.extend(lines)
    sys.stdout.write("\n".join(out_lines)+"\n")

def parse_cli(argv):
    # returns dict name-> value/True; may raise AppError; help flag
    result={}
    seen=set()
    positional_only=False
    i=0
    def register(spec, value=None):
        if spec.long in seen:
            raise AppError(f"option '--{spec.long}' cannot be specified more than once")
        seen.add(spec.long)
        result[spec.long]=value if spec.takes else True
    while i < len(argv):
        arg=argv[i]
        if positional_only:
            i+=1; continue
        if arg=='--':
            positional_only=True; i+=1; continue
        if arg.startswith('--') and len(arg)>2 and not arg.startswith('--='):
            body=arg[2:]
            if '=' in body:
                name, eqval = body.split('=',1)
                has_eq=True
            else:
                name, eqval = body, None; has_eq=False
            # resolve name exact or abbreviation
            if name in SPEC_BY_LONG:
                spec=SPEC_BY_LONG[name]
            else:
                matches=[s for s in OPT_SPECS if s.long.startswith(name) and name!='']
                if len(matches)==1:
                    spec=matches[0]
                elif len(matches)>1:
                    # format ambiguity
                    mstr=" and ".join([f"'--{m.long}'" for m in matches])
                    # Boost format: matches '--a', and '--b'
                    if len(matches)==2:
                        msg=f"option '--{name}' is ambiguous and matches '--{matches[0].long}', and '--{matches[1].long}'"
                    else:
                        msg=f"option '--{name}' is ambiguous and matches "+ ", ".join(f"'--{m.long}'" for m in matches)
                    raise AppError(msg)
                else:
                    raise AppError(f"unrecognised option '--{name}'")
            if has_eq:
                if eqval=='':
                    raise AppError(f"the argument for option '--{spec.long}' should follow immediately after the equal sign")
                if not spec.takes:
                    raise AppError(f"option '--{spec.long}' does not take any arguments")
