        s=[_SBOX[b] for b in s]
        s=shift_rows(s)
        s=mix_columns(s)
        s=[s[i]^rounds[rnd][i] for i in range(16)]
    s=[_SBOX[b] for b in s]
    s=shift_rows(s)
    s=[s[i]^rounds[10][i] for i in range(16)]
    return bytes(s)

def _evp_bytes_to_key(password_bytes, key_len=16, iv_len=16):
    out=b""; prev=b""
    while len(out) < key_len+iv_len:
        prev=hashlib.md5(prev+password_bytes).digest()
        out+=prev
    return out[:key_len], out[key_len:key_len+iv_len]

def aes_cfb_crypt(data, password, decrypt=False):
    # CFB128: encryption and decryption both use AES encrypt; feedback differs
    if isinstance(password,str): password=password.encode()
    key,iv=_evp_bytes_to_key(password)
    out=bytearray()
    feedback=iv
    for off in range(0,len(data),16):
        block=data[off:off+16]
        ks=_aes_encrypt_block(key, feedback)
        res=bytes(b ^ ks[i] for i,b in enumerate(block))
        out.extend(res)
        if len(block)==16:
            feedback = block if decrypt else res
        # partial final doesn't need feedback
    return bytes(out)

