class Color:
    def __init__(self, kind, value=None):
        self.kind=kind; self.value=value
    def __repr__(self): return f"Color({self.kind},{self.value})"
    def fg_sgr(self):
        if self.kind=='default': return '39'
        if self.kind=='ansi':
            n=self.value
            return str(30+n) if n<8 else str(90+(n-8))
        if self.kind=='256': return f'38;5;{self.value}'
        if self.kind=='rgb': return f'38;2;{self.value[0]};{self.value[1]};{self.value[2]}'
        return '39'
    def bg_sgr(self):
        if self.kind=='default': return '49'
        if self.kind=='ansi':
            n=self.value
            return str(40+n) if n<8 else str(100+(n-8))
        if self.kind=='256': return f'48;5;{self.value}'
        if self.kind=='rgb': return f'48;2;{self.value[0]};{self.value[1]};{self.value[2]}'
        return '49'
    def __eq__(self,other): return isinstance(other,Color) and self.kind==other.kind and self.value==other.value
    def __hash__(self): return hash((self.kind,str(self.value)))

DEFAULT_COLOR=Color('default')
def ansi_color(n): return Color('ansi',n)

class Style:
    __slots__=('fg','bg','flags')
    def __init__(self, fg=None,bg=None,flags=None):
        self.fg=fg if fg is not None else DEFAULT_COLOR
        self.bg=bg if bg is not None else DEFAULT_COLOR
        self.flags=set(flags) if flags else set()
    def copy(self): return Style(self.fg,self.bg,set(self.flags))
    def merged(self, other):
        # other applied after: fg/bg override only if not default, flags union
        r=self.copy()
        if other.fg.kind!='default': r.fg=other.fg
        if other.bg.kind!='default': r.bg=other.bg
        r.flags |= other.flags
        return r
    def with_dim_if(self, cond):
        r=self.copy()
        if cond: r.flags.add('dim')
        return r
    def __eq__(self,other): return isinstance(other,Style) and self.fg==other.fg and self.bg==other.bg and self.flags==other.flags
    def __hash__(self): return hash((self.fg,self.bg,tuple(sorted(self.flags))))

