def parse_cli(argv):
    # returns dict name-> value/True; may raise AppError; help flag
    result={}
    seen=set()
    positional_only=False
    i=0
    def register(spec, value=None):
        if spec.long in seen:
            raise AppError(f"option '--{spec.long}' cannot be specified more than once")
        seen.add(spec.long)
        result[spec.long]=value if spec.takes else True
    while i < len(argv):
        arg=argv[i]
        if positional_only:
            i+=1; continue
        if arg=='--':
            positional_only=True; i+=1; continue
        if arg.startswith('--') and len(arg)>2 and not arg.startswith('--='):
            body=arg[2:]
            if '=' in body:
                name, eqval = body.split('=',1)
                has_eq=True
            else:
                name, eqval = body, None; has_eq=False
            # resolve name exact or abbreviation
            if name in SPEC_BY_LONG:
                spec=SPEC_BY_LONG[name]
            else:
                matches=[s for s in OPT_SPECS if s.long.startswith(name) and name!='']
                if len(matches)==1:
                    spec=matches[0]
                elif len(matches)>1:
                    # format ambiguity
                    mstr=" and ".join([f"'--{m.long}'" for m in matches])
                    # Boost format: matches '--a', and '--b'
                    if len(matches)==2:
                        msg=f"option '--{name}' is ambiguous and matches '--{matches[0].long}', and '--{matches[1].long}'"
                    else:
                        msg=f"option '--{name}' is ambiguous and matches "+ ", ".join(f"'--{m.long}'" for m in matches)
                    raise AppError(msg)
                else:
                    raise AppError(f"unrecognised option '--{name}'")
            if has_eq:
                if eqval=='':
                    raise AppError(f"the argument for option '--{spec.long}' should follow immediately after the equal sign")
                if not spec.takes:
                    raise AppError(f"option '--{spec.long}' does not take any arguments")
                register(spec,eqval)
            else:
                if spec.takes:
                    # need next arg
                    if i+1>=len(argv):
                        raise AppError(f"the required argument for option '--{spec.long}' is missing")
                    nxt=argv[i+1]
                    # Do not consume recognized short option token (-c/-h or clusters starting with those)
                    if len(nxt)>=2 and nxt[0]=='-' and nxt[1]!='-' and nxt[1] in SPEC_BY_SHORT:
                        raise AppError(f"the required argument for option '--{spec.long}' is missing")
                    register(spec,nxt); i+=1
                else:
                    register(spec)
            i+=1; continue
        elif arg.startswith('-') and len(arg)>1 and arg!='-':
            # short cluster
            chars=arg[1:]
            # special: -c=foo etc handled in loop
            j=0
            while j < len(chars):
                ch=chars[j]
                if ch not in SPEC_BY_SHORT:
                    # Boost prints whole token for cases like -hfoo, -x
                    raise AppError(f"unrecognised option '{arg}'")
                spec=SPEC_BY_SHORT[ch]
                if spec.takes:
                    rest=chars[j+1:]
                    if rest:
                        if rest.startswith('='): rest=rest[1:]
                        register(spec,rest)
                    else:
                        if i+1>=len(argv):
                            raise AppError(f"the required argument for option '--{spec.long}' is missing")
                        nxt=argv[i+1]
                        if len(nxt)>=2 and nxt[0]=='-' and nxt[1]!='-' and nxt[1] in SPEC_BY_SHORT:
                            raise AppError(f"the required argument for option '--{spec.long}' is missing")
                        register(spec,nxt); i+=1
                    j=len(chars); break
                else:
                    # bool short: if there are more chars, boost handling:
                    # -hh will register twice (duplicate error on loop)
                    # -hc will continue to next char
                    # -hfoo will raise unrecognised for whole token if next char not a known short
                    register(spec)
                    j+=1
                    if j < len(chars) and chars[j] not in SPEC_BY_SHORT:
                        raise AppError(f"unrecognised option '{arg}'")
                    continue
            i+=1; continue
        else:
            # positional, ignored
            i+=1; continue
    return result

