class CalEvent:
    __slots__=('category','name','day','month')
    def __init__(self,cat,name,day,month): self.category=cat; self.name=name; self.day=day; self.month=month

def load_events(root):
    events=[]  # list
    window=14
    cat_root=root.get_path(['calendar-events'])
    if cat_root is None:
        return events, window
    # window via boost-like get with default: invalid lexical -> default
    wv=cat_root.get_str(['recent-events-window'])
    if wv is not None:
        # try unsigned int parsing strictly (whole string trimmed)
        t=trim(wv)
        # boost lexical for unsigned: negative wraps; we model: if matches -?\d+ and within ... 
        if re.fullmatch(r'-?\d+',t):
            try:
                n=int(t)
                if n<0: window= (n & 0xffffffff)
                elif n>0xffffffff: window=14
                else: window=n
            except: window=14
        else:
            window=14
    # categories: children of calendar-events other than recent-events-window
    # Each child is a group name node; its children are index nodes; each index node has name/date children.
    for group_name, group_node in cat_root.children.items():
        if group_name=='recent-events-window':
            continue
        # group_node should have index children
        # If group_node has direct name/date (no index), the actual key would be calendar-events.<group> -> invalid
        # Detect: if it has a child 'name' or 'date' or no children etc, treat invalid
        # Determine if all children are index-like (any name). Original check counts components in the full key of a node that has name/date leaves.
        # Simpler: for each descendant leaf 'name', compute its key path; validate.
        # We can iterate grandchildren:
        # if group has direct name/date children -> invalid key calendar-events.<group>
        if 'name' in group_node.children or 'date' in group_node.children:
            raise AppError(f"Invalid calendar event key: calendar-events.{group_name}")
        for index_name, idx_node in group_node.children.items():
            # idx_node must have name/date; if it has extra subnodes (e.g., sub), the leaf path would be calendar-events.group.index.sub -> invalid.
            # Check for deeper nesting
            for child_name, child_node in idx_node.children.items():
                if child_name not in ('name','date'):
                    raise AppError(f"Invalid calendar event key: calendar-events.{group_name}.{index_name}.{child_name}")
                if child_node.children:
                    # deeper e.g. name.x
                    sub=list(child_node.children.keys())[0]
                    raise AppError(f"Invalid calendar event key: calendar-events.{group_name}.{index_name}.{child_name}.{sub}")
            name_node=idx_node.child('name')
            if name_node is None:
                raise AppError("No such node (name)")
            date_node=idx_node.child('date')
            if date_node is None:
                raise AppError("No such node (date)")
            name=name_node.value
            datestr=date_node.value
            # parse date format: regex searching prefixed %d.%d pattern 1-2 digits
            m=re.match(r'^(\d{1,2})\.(\d{1,2})', datestr)
            if not m:
                raise AppError(f"Invalid date format: {datestr}")
            # Must ensure first char formatting? Regex match anchored, and after day dot month; 009 fails because \d{1,2} then dot expectation
            day=int(m.group(1)); month=int(m.group(2))
            events.append(CalEvent(group_name,name,day,month))
    return events, window

