TAG_RE=re.compile(r'^\* ([a-z0-9 \-]+?)(?:\s*\(.+\)|\s*\(.+\)\s*)?(?::.*)?$')
# We'll implement tag parse manually for more control
def parse_tag_name(line_lower_trimmed):
    # line is already left-trimmed and ascii-lowered; must start with "* "
    if not line_lower_trimmed.startswith('* '):
        return None
    rest=line_lower_trimmed[2:]
    # regex pattern matching original behaviour approx
    # Use a compiled full regex with optional paren / colon; must consume whole string
    m=re.match(r'^([a-z0-9 \-]+?)(?:\s*\(.+\)\s*)?(?::.*)?$', rest)
    # But this allows space before colon after paren (undesired). We'll handle with manual checking:
    # Find colon/paren structures:
    # Strategy: try regex variants:
    patterns=[
        r'^([a-z0-9 \-]+?)\s*\((.+)\)(?::.*)?$',  # paren, colon must immediately follow ) (handled because after ) either colon or end; \s* between name and paren allowed)
        r'^([a-z0-9 \-]+?)(?::.*)?$', # no paren, colon can follow after spaces captured in name
    ]
    # Variant1 must be strict: after closing paren (greedy to last )), remainder must be empty or start with ':'
    # Greedy paren: find first '('
    if '(' in rest:
        idx=rest.find('(')
        name_part=rest[:idx]
        # name part chars and trimming
        if not re.fullmatch(r'[a-z0-9 \-]+?\s*', name_part):
            return None
        # paren must close at some last ')' ; remainder after last ')'
        last=rest.rfind(')')
        if last < idx+1: # need at least one char between parens (?) content length >=1
            return None
        content=rest[idx+1:last]
        if len(content)<1:
            return None
        remainder=rest[last+1:]
        if remainder=='' or remainder.startswith(':'):
            name=name_part.strip()
            if not name: return None
            return name
        else:
            return None
    else:
        # no paren
        # colon split
        if ':' in rest:
            name_part=rest.split(':',1)[0]
        else:
            name_part=rest
        if not re.fullmatch(r'[a-z0-9 \-]+', name_part):
            return None
        name=name_part.strip()
        if not name: return None
        return name

class LogEntry:
    __slots__=('date','path','content','lines','sections','section_tags','root_tags','all_tags')
    def __init__(self,dt,path,content):
        self.date=dt; self.path=path; self.content=content
        # content is bytes decoded surrogateescape; splitlines by \n preserving? For parsing use .split('\n')
        if isinstance(content,bytes):
            text=content.decode('utf-8',errors='surrogateescape')
        else: text=content
        self.lines=text.split('\n')
        # If file ends with \n, split gives trailing '' line; preview display uses lines as in original: they likely read via getline so trailing empty not a line.
        # Remove final empty element from trailing newline for parsing/preview? getline behavior: last newline doesn't create extra line.
        # But a file with "\n\n" at end: getline yields one empty line after first? We'll keep logic: content.split('\n') and if content endswith \n, drop last ''.
        if text.endswith('\n'):
            self.lines=self.lines[:-1]
        self.sections=set() # names present (excluding root)
        self.section_tags={} # section name or None for root -> set(tags)
        self.root_tags=set()
        self.all_tags=set()

def parse_log_entry(dt,path,content, first_line_section=False):
    entry=LogEntry(dt,path,content)
    current_section=None  # None = root
    for idx, raw_line in enumerate(entry.lines):
        line_lower=ascii_lower(raw_line)
        # strip leading spaces/tabs for detection
        stripped=line_lower.lstrip(' \t')
        # Section
        if stripped.startswith('# '):
            if idx==0 and not first_line_section:
                pass
            else:
                name=stripped[2:].strip()
                if name:
                    current_section=name
                    entry.sections.add(name)
                    # Repeated section resets its tags
                    entry.section_tags[name]=set()
                    continue
                else:
                    # Empty section name: ignored (does not change current)
                    continue
        # Tag
        if stripped.startswith('* '):
            tag=parse_tag_name(stripped)
            if tag is not None:
                if current_section is None:
                    entry.root_tags.add(tag)
                else:
                    if current_section not in entry.section_tags:
                        entry.section_tags[current_section]=set()
                    entry.section_tags[current_section].add(tag)
                entry.all_tags.add(tag)
    # root as section presence is implicit if root_tags non-empty
    return entry

