ANSI16_NAMES={
    'black':0,'red':1,'green':2,'yellow':3,'blue':4,'magenta':5,'cyan':6,'white':7,
    'brightblack':8,'brightred':9,'brightgreen':10,'brightyellow':11,'brightblue':12,'brightmagenta':13,'brightcyan':14,'brightwhite':15,
    'gray':8,'grey':8,
}
def parse_color(raw, context_path):
    # raw is trimmed value as in config
    s=raw.strip()
    low=ascii_lower(s)
    def err(msg):
        raise AppError(f"Invalid {context_path} ({raw}): {msg}")
    if low=='default':
        return Color('default')
    # rgb / rgba
    if low.startswith('rgb(') and s.endswith(')'):
        inner=s[4:-1]
        parts=[p.strip() for p in inner.split(',')]
        if len(parts)!=3:
            err(f"RGB color expects 3 values: {raw}")
        try: vals=[int(p) for p in parts]
        except: err(f"Invalid color format: {raw}")
        if any(v<0 or v>255 for v in vals):
            err(f"RGB values out of range: {raw}")
        return Color('rgb',tuple(vals))
    if low.startswith('rgba(') and s.endswith(')'):
        inner=s[5:-1]
        parts=[p.strip() for p in inner.split(',')]
        if len(parts)!=4:
            err(f"RGBA color expects 4 values: {raw}")
        try: vals=[int(p) for p in parts]
        except: err(f"Invalid color format: {raw}")
        if any(v<0 or v>255 for v in vals):
            err(f"RGBA values out of range: {raw}")
        return Color('rgb',tuple(vals[:3]))
    if low.startswith('ansi16(') and s.endswith(')'):
        inner=s[7:-1].strip()
        inner_low=ascii_lower(inner)
        if inner_low in ANSI16_NAMES:
            return Color('ansi',ANSI16_NAMES[inner_low])
        # numeric
        try:
            # Must be integer plain
            if not re.fullmatch(r'-?\d+',inner): raise ValueError()
            n=int(inner)
        except:
            err(f"Unknown ansi16 color name: {inner}")
        if n<0 or n>15:
            err(f"ansi16 value out of range: {raw}")
        return Color('ansi',n)
    if low.startswith('ansi256(') and s.endswith(')'):
        inner=s[8:-1].strip()
        try:
            if not re.fullmatch(r'-?\d+',inner): raise ValueError()
            n=int(inner)
        except: err(f"Invalid color format: {raw}")
        if n<0 or n>255:
            err(f"ansi256 value out of range: {raw}")
        return Color('256',n)
    if s.startswith('#'):
        hexpart=s[1:]
        if len(hexpart)!=6:
            err(f"Invalid hex color format: {raw}")
        try:
            # validate hex
            vals=tuple(int(hexpart[i:i+2],16) for i in (0,2,4))
        except:
            err(f"Invalid hex color value: {raw}")
        return Color('rgb',vals)
    err(f"Invalid color format: {raw}")

