    def __init__(self, settings):
        self.settings=settings
        self.entries_by_year={} # year -> dict date->LogEntry
        self.years=set()
        self.scratchpads=[] # list dict name/path/mtime_date/date_str
        self.load_all()
    def log_dir(self): return self.settings.log_dir
    def ensure_dirs(self):
        # create directories log_dir and scratchpads - mimic std::filesystem::create_directories errors
        try:
            os.makedirs(self.settings.log_dir,exist_ok=True)
        except FileExistsError:
            # existing is file
            raise AppError(f"filesystem error: cannot create directories: File exists [{self.settings.log_dir}]")
        except PermissionError:
            raise AppError(f"filesystem error: cannot create directories: Permission denied [{self.settings.log_dir}]")
        except OSError as e:
            raise AppError(f"filesystem error: cannot create directories: {e.strerror} [{self.settings.log_dir}]")
        sp=os.path.join(self.settings.log_dir,'scratchpads')
        try: os.makedirs(sp,exist_ok=True)
        except FileExistsError:
            raise AppError(f"filesystem error: cannot create directories: File exists [{sp}]")
        except PermissionError:
            raise AppError(f"filesystem error: cannot create directories: Permission denied [{sp}]")
        except OSError as e:
            raise AppError(f"filesystem error: cannot create directories: {e.strerror} [{sp}]")
    def load_all(self):
        self.entries_by_year={}
        self.years=set()
        if not os.path.isdir(self.settings.log_dir):
            return
        # iterate entries - year directories
        try: entries=list(os.scandir(self.settings.log_dir))
        except: entries=[]
        for entry in entries:
            if entry.is_dir() and re.fullmatch(r'y\d{4}',entry.name):
                year=int(entry.name[1:])
                self.years.add(year)
                year_map={}
                # probe each day of year
                if valid_date(year,1,1):
                    dt=datetime.date(year,1,1)
                    while dt.year==year:
                        path=self.path_for_date(dt)
                        if os.path.isfile(path):
                            content=self.read_file_content(path)
                            if content is not None:
                                ent=parse_log_entry(dt,path,content,self.settings.first_line_section)
                                year_map[dt]=ent
                        # next day
                        dt += datetime.timedelta(days=1)
                        if dt.year!=year: break
                self.entries_by_year[year]=year_map
        self.load_scratchpads()
    def path_for_date(self,dt):
        year_dir=os.path.join(self.settings.log_dir,f"y{dt.year:04d}")
        filename=strftime_format(self.settings.log_name_format,dt)
        return os.path.join(year_dir,filename)
    def read_file_content(self,path):
        try:
            data=open(path,'rb').read()
        except:
            return None
        if self.settings.password and is_encrypted(self.settings.log_dir):
            data=aes_cfb_crypt(data,self.settings.password,decrypt=True)
        # If not encrypted but file is binary, decode surrogate
        return data
    def load_scratchpads(self):
        spdir=os.path.join(self.settings.log_dir,'scratchpads')
        items=[]
        if os.path.isdir(spdir):
            for entry in os.scandir(spdir):
                if entry.is_file():
                    try: st=entry.stat()
                    except: continue
                    # displayed date: mtime conversion with tiny offset like original? Use localtime date of mtime.
                    # For exactly midnight, original showed previous day due to conversion race; approximate by subtracting a micro-epsilon: use datetime from timestamp - 1 micro? That would affect times exactly midnight only in practice (timestamp exactly .0). If mtime nanos are 0 and time is midnight, subtract 1 sec.
                    ts=st.st_mtime
                    # st_mtime is float seconds; check if exact second and local time midnight
                    lt=time.localtime(ts)
                    if lt.tm_hour==0 and lt.tm_min==0 and lt.tm_sec==0:
                        ts-=1
                    dtime=datetime.datetime.fromtimestamp(ts)
                    items.append({'name':entry.name,'path':entry.path,'mtime':st.st_mtime,'date_obj':dtime.date(),'date_str':f"{dtime.year%100:02d}-{dtime.month:02d}-{dtime.day:02d}"})
            # stable sort by displayed date descending (per original: sort by date only)
            items.sort(key=lambda x: x['date_obj'], reverse=True)
        self.scratchpads=items
    def entries_for_year(self,year):
        return self.entries_by_year.get(year,{})
    def reload_year(self,year):
        # reload all (simpler)
        self.load_all()
    def reload(self):
        self.load_all()

