def format_to_regex(fmt):
    # Returns (regex_pattern_for_basename_or_relative, captured_order_list, has_year)
    # Tokens produce groups.
    order=[]
    pat=''
    i=0
    while i < len(fmt):
        if fmt[i]=='%' and i+1<len(fmt):
            tok=fmt[i+1]
            if tok=='Y': pat+=r'(\d{4})'; order.append('Y')
            elif tok=='y': pat+=r'(\d{2})'; order.append('y')
            elif tok=='m': pat+=r'(\d{2})'; order.append('m')
            elif tok=='d': pat+=r'(\d{2})'; order.append('d')
            elif tok=='b': pat+=r'([A-Za-z]{3})'; order.append('b')
            elif tok=='B': pat+=r'([A-Za-z]+)'; order.append('B')
            elif tok=='%': pat+=r'%'
            elif tok=='H': pat+=r'(\d{2})'; order.append('H')
