# ---------------- git handling -----------------
def git_run(root,args,extra_env=None):
    env=dict(os.environ)
    if extra_env: env.update(extra_env)
    # prevent credential prompts
    env.setdefault('GIT_TERMINAL_PROMPT','0')
    return subprocess.run(['git','-C',root]+args,capture_output=True,text=True,env=env,timeout=30)

class GitErrorInfo(Exception):
    def __init__(self, line, message, prefix=None):
        self.line=line; self.message=message; self.prefix=prefix
    def display(self):
        return f"Git error @/workspace/source/utils/git_repo.cpp:{self.line}{self.message}"

def git_repo_open_or_fatal(settings):
    root=settings.git_repo_root
    # check with git rev-parse
    try:
