    except Exception:
        r=None
    if r is None or r.returncode!=0:
        # libgit message
        raise AppError(f"Git error @/workspace/source/utils/git_repo.cpp:95\n\tcould not find repository from '{root}'")

def git_ssh_env(settings):
    # For ssh remotes, git CLI uses ssh command; for local paths it's ignored
    key=settings.git_ssh_key
    if key:
        return {'GIT_SSH_COMMAND':f"ssh -i {key} -o IdentitiesOnly=yes -o StrictHostKeyChecking=no -o UserKnownHostsFile=/dev/null"}
    return {}

def git_do_pull(settings):
    """return None on success, or error display string on failure"""
    root=settings.git_repo_root; remote=settings.git_remote; branch=settings.git_branch
    # remote lookup
    try:
        r=git_run(root,['remote','get-url',remote])
    except Exception as e:
        return f"Git error @/workspace/source/utils/git_repo.cpp:213remote '{remote}' does not exist"
    if r.returncode!=0:
        return f"Git error @/workspace/source/utils/git_repo.cpp:213remote '{remote}' does not exist"
    # fetch
    try:
        r=git_run(root,['fetch',remote],extra_env=git_ssh_env(settings))
    except Exception:
        return f"Git error @/workspace/source/utils/git_repo.cpp:218unsupported URL protocol"
    if r.returncode!=0:
        msg=(r.stderr or r.stdout or '').strip()
        # Map common git errors to libgit like messages. Original for nonexistent local path gave unsupported URL protocol
        if 'unsupported' in msg.lower() or 'does not exist' in msg.lower() or 'no such' in msg.lower() or 'could not read from remote' in msg.lower():
            libmsg='unsupported URL protocol'
        else:
            # take last line stripped of 'fatal: '
            lines=[l for l in msg.splitlines() if l.strip()]
            libmsg=lines[-1].replace('fatal: ','').strip() if lines else 'unsupported URL protocol'
        return f"Git error @/workspace/source/utils/git_repo.cpp:218{libmsg}"
    # merge fast-forward if remote branch exists
    # Check remote branch
    r=git_run(root,['rev-parse','--verify',f"refs/remotes/{remote}/{branch}"])
    if r.returncode!=0:
        # No remote branch (empty repo) -> considered success? Original might fail merge lookup; ignore
        return None
    remote_oid=r.stdout.strip()
    # HEAD exists?
    h=git_run(root,['rev-parse','--verify','HEAD'])
    if h.returncode!=0:
        # checkout remote branch as local
        git_run(root,['update-ref',f'refs/heads/{branch}',remote_oid])
        git_run(root,['checkout','-f',branch])
        return None
    local_oid=h.stdout.strip()
    if local_oid==remote_oid:
        return None
    # Is local ancestor of remote?
    a=git_run(root,['merge-base','--is-ancestor',local_oid,remote_oid])
    if a.returncode==0:
        m=git_run(root,['merge','--ff-only',f"{remote}/{branch}"])
        if m.returncode!=0:
            msg=(m.stderr or m.stdout or '').strip().splitlines()
            libmsg=msg[-1] if msg else 'merge failed'
            return f"Git error @/workspace/source/utils/git_repo.cpp:230{libmsg}"
        return None
    # remote ancestor of local?
    a2=git_run(root,['merge-base','--is-ancestor',remote_oid,local_oid])
    if a2.returncode==0:
        return None
    # diverged: attempt merge
    m=git_run(root,['merge',f"{remote}/{branch}","-m","Merge remote"])
    if m.returncode!=0:
        git_run(root,['merge','--abort'])
        msg=(m.stderr or m.stdout or '').strip().splitlines()
        libmsg=msg[-1] if msg else 'merge failed'
        return f"Git error @/workspace/source/utils/git_repo.cpp:230{libmsg}"
    return None

