        for ch in text:
            if max_x is not None and cx>=max_x: break
            if cx>=self.w: break
            w=char_width(ch)
            if w==0:
                continue
            if cx>=0:
                self.set(cx,y,ch,style)
                # mark continuation cells blank with same style? For wide chars, set next cell to '' placeholder
                if w==2 and cx+1<self.w:
                    self.cells[y][cx+1]=Cell('',style)
            cx+=w
    def fill(self,x,y,w,h,style):
        for yy in range(y,y+h):
            for xx in range(x,x+w): self.set(xx,yy,' ',style)
    def box(self,x,y,w,h,border_style_name='rounded',style=None,title=None,title_style=None, fill=False):
        if style is None: style=PLAIN
        if title_style is None: title_style=style
        chars=BORDER_CHARS.get(border_style_name,BORDER_CHARS['rounded'])
        tl,tr,bl,br,hz,vt=chars
        if w<=0 or h<=0: return
        if fill: self.fill(x,y,w,h,style)
        # top/bottom
        for xx in range(x,x+w):
            self.set_line_cell(xx,y,hz,style,border_style_name)
            self.set_line_cell(xx,y+h-1,hz,style,border_style_name)
        for yy in range(y,y+h):
            self.set_line_cell(x,yy,vt,style,border_style_name)
            self.set_line_cell(x+w-1,yy,vt,style,border_style_name)
        self.set_line_cell(x,y,tl,style,border_style_name)
        self.set_line_cell(x+w-1,y,tr,style,border_style_name)
        self.set_line_cell(x,y+h-1,bl,style,border_style_name)
        self.set_line_cell(x+w-1,y+h-1,br,style,border_style_name)
        if title:
            # title written over top border starting x+1
            t=sanitize_text(title)
            for i,ch in enumerate(t):
                if x+1+i >= x+w-1: break
                self.set(x+1+i,y,ch,title_style)
    def set_line_cell(self,x,y,ch,style,border_style_name='rounded'):
        if not self.in_bounds(x,y): return
        old=self.cells[y][x].ch
        merged=merge_line_char(old,ch)
        self.cells[y][x]=Cell(merged,style)
    def vscroll(self,x,y_top,y_bottom,total,visible,start):
        # y_top/y_bottom inclusive border rows? content rows between: caller gives content row range
        # We'll accept content top and bottom inclusive
        if total<=visible or visible<=0: return
        height=visible
        thumb_start_frac=start/total
        thumb_end_frac=(start+visible)/total
        for idx in range(height):
            y=y_top+idx
            cell_start=idx/height; cell_end=(idx+1)/height
            overlap=min(cell_end,thumb_end_frac)-max(cell_start,thumb_start_frac)
            if overlap<=0.001:
                ch='│'
            elif overlap>= (cell_end-cell_start)-0.001:
                ch='┃'
            elif cell_start < thumb_start_frac:
                ch='╻'
            else:
                ch='╹'
            # Keep style of existing cell (border)
            if self.in_bounds(x,y):
                old_style=self.cells[y][x].style
                self.cells[y][x]=Cell(ch,old_style)

