def merge_line_char(old,new):
    if old not in LINE_MASKS or new not in LINE_MASKS:
        return new
    om=LINE_MASKS[old]; nm=LINE_MASKS[new]
    merged=tuple(1 if (om[i] or nm[i]) else 0 for i in range(4))
    return MASK_TO_CHAR.get(merged,new)

def sanitize_text(s):
    out=[]
    for ch in s:
        o=ord(ch)
        if ch=='\t' or o<32 or o==127:
            continue
        out.append(ch)
    return ''.join(out)
def char_width(ch):
    if ch=='\t': return 0
    o=ord(ch)
    if o<32 or o==127: return 0
    if unicodedata.combining(ch): return 0
    eaw=unicodedata.east_asian_width(ch)
    if eaw in ('W','F'): return 2
    return 1
def text_width(s):
    return sum(char_width(c) for c in sanitize_text(s))
def clip_text(s,width):
    out=''; w=0
    for ch in sanitize_text(s):
        cw=char_width(ch)
        if w+cw>width: break
        out+=ch; w+=cw
    return out
def add_dim(style):
    r=style.copy(); r.flags.add('dim'); return r
def apply_focus_dim(style, dimmed):
    return add_dim(style) if dimmed else style

class Terminal:
    def __init__(self):
        self.fd_in=sys.stdin.fileno() if hasattr(sys.stdin,'fileno') else 0
        self.fd_out=sys.stdout.fileno() if hasattr(sys.stdout,'fileno') else 1
        self.old_term=None
        self.raw=False
        self.resize_needed=True
        self.in_alt=False
    def size(self):
        try:
            sz=shutil.get_terminal_size((80,24))
            return max(1,sz.columns),max(1,sz.lines)
        except:
            return 80,24
    def enter(self):
        # Set raw if tty
        try:
            import termios
            self.old_term=termios.tcgetattr(self.fd_in)
            new=termios.tcgetattr(self.fd_in)
            # raw-like: Based on termios raw but keep output processing? FTXUI sets many flags.
            new[0]=new[0] & ~(termios.BRKINT | termios.ICRNL | termios.INPCK | termios.ISTRIP | termios.IXON)
            new[1]=new[1] & ~(termios.OPOST)
            new[2]=new[2] | termios.CS8
            new[3]=new[3] & ~(termios.ECHO | termios.ICANON | termios.IEXTEN | termios.ISIG)
            new[6][termios.VMIN]=0
            new[6][termios.VTIME]=1
            termios.tcsetattr(self.fd_in,termios.TCSAFLUSH,new)
            self.raw=True
        except Exception:
            self.raw=False
        os.write(self.fd_out,b"\x1b[?1049h\x1b[?7l\x1b[?25l")
        self.in_alt=True
    def leave(self):
        if self.in_alt:
            os.write(self.fd_out,b"\x1b[?25h\x1b[?7h\x1b[?1049l")
            self.in_alt=False
        if self.raw and self.old_term is not None:
            try:
                import termios; termios.tcsetattr(self.fd_in,termios.TCSAFLUSH,self.old_term)
            except: pass
            self.raw=False
    def suspend(self):
        self.leave()
    def resume(self):
        self.enter()
    def render(self,buf):
        w,h=buf.w,buf.h
        out=[]
        out.append("\x1b[H")
        # disable wrap already
        cur_style=None
        for y in range(h):
            # trim trailing spaces: find last non-space cell (or styled non-space)
            last=w-1
            while last>=0:
                c=buf.cells[y][last]
                if c.ch not in (' ','') or c.style!=PLAIN:
                    # If style is plain and char space, trim; if char is '' the wide previous will be found
                    if c.ch==' ' and c.style==PLAIN:
                        last-=1; continue
                    break
                last-=1
            # Actually compute above accurately simple:
            # build row
            row_parts=[]
            for x in range(last+1):
                cell=buf.cells[y][x]
                if cell.ch=='':
                    continue
                st=cell.style
                if st!=cur_style:
                    row_parts.append("\x1b[0m")
                    sgr=style_sgr(st)
                    if sgr: row_parts.append(f"\x1b[{sgr}m")
                    cur_style=st
                row_parts.append(cell.ch)
            out.append(''.join(row_parts))
            if y<h-1: out.append("\r\n")
        out.append("\x1b[0m\x1b[?25l")
        try: os.write(self.fd_out,''.join(out).encode('utf-8',errors='replace'))
        except: pass

# Key event
class Key:
    def __init__(self,kind,char=''):
        self.kind=kind; self.char=char
    def __repr__(self): return f"Key({self.kind},{self.char!r})"

def parse_key_from_buffer(data, pos):
    """data bytes starting at pos, return (Key,newpos) or (None,pos) if incomplete"""
    if pos>=len(data): return None,pos
    b=data[pos]
    if b==0x1b:
        # parse sequences
        if pos+1>=len(data): return None,pos # incomplete/escape
        nxt=data[pos+1]
        if nxt==ord('['):
            # CSI until final byte 0x40-0x7e
            j=pos+2
            while j<len(data) and not (0x40 <= data[j] <= 0x7e): j+=1
            if j>=len(data): return None,pos
            final=chr(data[j]); params=data[pos+2:j].decode('ascii',errors='ignore')
            seq=data[pos:j+1]
            # mouse ignore
            if final in ('M','m') or '<' in params: return Key('mouse'),j+1
            mapping={'A':'up','B':'down','C':'right','D':'left','H':'home','F':'end','Z':'btab'}
            if final in mapping: return Key(mapping[final]),j+1
            if final=='~':
                code=params.split(';')[0]
                m2={'1':'home','2':'insert','3':'delete','4':'end','5':'pageup','6':'pagedown','7':'home','8':'end','11':'f1','12':'f2','13':'f3','14':'f4','15':'f5','17':'f6','18':'f7','19':'f8','20':'f9','21':'f10','23':'f11','24':'f12'}
                return Key(m2.get(code,'unknown')),j+1
            if final=='P': return Key('f1'),j+1
            if final=='Q': return Key('f2'),j+1
            if final=='R': return Key('f3'),j+1
            if final=='S': return Key('f4'),j+1
            return Key('unknown'),j+1
        elif nxt==ord('O'):
            if pos+2>=len(data): return None,pos
            c=chr(data[pos+2])
            mapping={'A':'up','B':'down','C':'right','D':'left','H':'home','F':'end','P':'f1','Q':'f2','R':'f3','S':'f4'}
            return Key(mapping.get(c,'unknown')),pos+3
        else:
            # Alt+char or Escape: treat as escape if next is not a printable starting a sequence? ESC followed by char in input is alt; original likely Escape.
            return Key('escape'),pos+1
    elif b in (13,10): return Key('enter'),pos+1
    elif b==9: return Key('tab'),pos+1
    elif b==127: return Key('backspace'),pos+1
    elif b==8: return Key('backspace'),pos+1
    elif b==3: return Key('ctrl_c'),pos+1
    elif b<32:
        return Key('control',chr(b)),pos+1
    else:
        # utf8 char
        # determine length
        if b<0x80: l=1
        elif b>=0xf0: l=4
        elif b>=0xe0: l=3
        elif b>=0xc0: l=2
        else: l=1
        if pos+l>len(data): return None,pos
        try: ch=data[pos:pos+l].decode('utf-8')
        except: ch='?'
        return Key('char',ch),pos+l

