# -------------- Markdown rendering ----------------
def md_inline_segments(text, mdtheme, base_style):
    # Returns segments list (text,Style). Base_style includes possible dim wrapping handled by caller merging.
    segments=[]
    def plain_style(): return base_style.copy()
    def code_style(): return Style(mdtheme['code-fg'],DEFAULT_COLOR,set(base_style.flags))
    # Scanner
    i=0; buf=''
    def flush():
        nonlocal buf
        if buf: segments.append((buf,plain_style())); buf=''
    while i<len(text):
        # code span
        if text[i]=='`':
            # double backtick: treat as code delimiter `` ... ``
            if text.startswith('``',i):
                end=text.find('``',i+2)
                if end!=-1:
                    flush(); segments.append(('``',plain_style())); segments.append((text[i+2:end],code_style())); segments.append(('``',plain_style())); i=end+2; continue
            end=text.find('`',i+1)
            if end!=-1:
                flush(); segments.append(('`',plain_style())); segments.append((text[i+1:end],code_style())); segments.append(('`',plain_style())); i=end+1; continue
            buf+=text[i]; i+=1; continue
        # bold/italic/strike delimiters
        matched=False
        for delim,flag in [('**','bold'),('__','bold'),('~~','strikethrough')]:
            if text.startswith(delim,i):
                end=text.find(delim,i+len(delim))
                if end!=-1 and end>i+len(delim):
                    flush(); segments.append((delim,plain_style()))
                    st=plain_style(); st.flags.add(flag); segments.append((text[i+len(delim):end],st)); segments.append((delim,plain_style())); i=end+len(delim); matched=True; break
        if matched: continue
        # single * or _ italic (not when followed by space? Original had *no* works, snake_case partial)
        if text[i] in ('*','_'):
            delim=text[i]
            end=text.find(delim,i+1)
            if end!=-1 and end>i+1:
                # To handle intra-word underscore: original colored snake 'case'?? It actually styled _name and a_ (observed _ separated). It uses italic matching too.
                flush(); segments.append((delim,plain_style())); st=plain_style(); st.flags.add('italic'); segments.append((text[i+1:end],st)); segments.append((delim,plain_style())); i=end+1; continue
        buf+=text[i]; i+=1
    flush()
    if not segments: segments.append(('',plain_style()))
    return segments

def render_md_line(line, mdtheme, in_code):
    """return (segments, in_code_after) where segments are (text,Style with no component dim yet)"""
    raw=line
    stripped=raw.lstrip(' \t')
    # Fenced code
    if stripped.startswith('```'):
        st=Style(mdtheme['code-fg'],DEFAULT_COLOR,{'dim'})
        return [(raw,st)], (not in_code)
    if in_code:
        st=Style(mdtheme['code-fg'],DEFAULT_COLOR,set())
        return [(raw,st)], True
    # Header
    m=re.match(r'^(#+) ',raw)
    if m:
        lvl=min(len(m.group(1)),6)
        key=f'header{lvl}'
        flags={'bold'} if lvl in (1,2) else set()
        st=Style(mdtheme[key],DEFAULT_COLOR,flags)
        return [(raw,st)], False
    # Quote
    if stripped.startswith('>'):
        # Only first '>' (after leading spaces?) colored
        # Find position of '>' in raw
        pos=raw.find('>')
        segs=[]
        if pos>0: segs.append((raw[:pos],Style()))
        segs.append(('>',Style(mdtheme['quote'],DEFAULT_COLOR,set())))
        segs.extend(md_inline_segments(raw[pos+1:],mdtheme,Style()))
        return segs,False
    # List marker
    lm=re.match(r'^(\s*)([-*+]\s|\d+[.)]\s)',raw)
    if lm:
        marker_end=lm.end()
        # marker text excluding trailing space for style; the space stays plain
        marker=lm.group(2)
        # split marker delim and space
        # marker group includes one trailing space
        delim=marker[:-1] if marker.endswith(' ') else marker
        prefix=lm.group(1)
        segs=[]
        if prefix: segs.append((prefix,Style()))
        segs.append((delim,Style(mdtheme['list'],DEFAULT_COLOR,{'bold'})))
        if marker.endswith(' '): segs.append((' ',Style()))
        # Inline on remainder
        segs.extend(md_inline_segments(raw[marker_end:],mdtheme,Style()))
        return segs,False
    return md_inline_segments(raw,mdtheme,Style()),False

