    # ----- data helpers -----
    def entries(self):
        if self.repo is None: return {}
        return self.repo.entries_for_year(self.display_year)
    def sections_data(self):
        entries=self.entries()
        counts={}
        root_count=0
        for ent in entries.values():
            if ent.root_tags: root_count+=1
            for sec in ent.sections:
                counts[sec]=counts.get(sec,0)+1
        data=[]
        if root_count:
            data.append(('<root section>',root_count,True))
        for name in sorted(counts.keys()):
            data.append((name,counts[name],False))
        # Sort overall by display name, root name is "<root section>". But we already inserted root first; sorting regular names could be < root? Names starting with characters < '<' (digits etc) should sort before. Re-sort all by name:
        all_data=[]
        if root_count: all_data.append(('<root section>',root_count,True))
        for name,c in counts.items(): all_data.append((name,c,False))
        all_data.sort(key=lambda x: x[0])
        return all_data
    def selected_section(self):
        data=self.sections_data()
        if self.sec_index<=0 or self.sec_index>len(data): return None
        name,count,is_root=data[self.sec_index-1]
        return (name,is_root)
    def tags_data(self):
        entries=self.entries()
        sel=self.selected_section()
        counts={}
        for ent in entries.values():
            tags=set()
            if sel is None:
                tags=ent.all_tags
            else:
                name,is_root=sel
                if is_root: tags=set(ent.root_tags)
                else: tags=set(ent.section_tags.get(name,set()))
            for t in tags: counts[t]=counts.get(t,0)+1
        return [(name,counts[name]) for name in sorted(counts.keys())]
    def selected_tag(self):
        data=self.tags_data()
        if self.tag_index<=0 or self.tag_index>len(data): return None
        return data[self.tag_index-1][0]
    def is_highlighted(self,ent):
        sec=self.selected_section(); tag=self.selected_tag()
        if sec is None and tag is None: return False
        if sec is not None and tag is None:
            name,is_root=sec
            return bool(ent.root_tags) if is_root else (name in ent.sections)
        if sec is None and tag is not None:
            return tag in ent.all_tags
        name,is_root=sec
        if is_root: return tag in ent.root_tags
        return tag in ent.section_tags.get(name,set())
    def events_for_date(self,dt):
        res=[]
        # categories sorted, names sorted
        by_cat={}
        for ev in self.events:
            if ev.day==dt.day and ev.month==dt.month:
                by_cat.setdefault(ev.category,[]).append(ev.name)
        for cat in sorted(by_cat.keys()):
            names=sorted(by_cat[cat])
            res.append((cat,names))
        return res
    def today_event_top(self):
        s=''
        for ev in sorted(self.events, key=lambda e:(e.category,e.name)):
            if ev.day==self.today.day and ev.month==self.today.month:
                s=f"{ev.category} - {ev.name}"
        return s
    def recent_events(self):
        # return list of (category, [(event,diff)])
        groups={}
        total=0
        for ev in self.events:
            # compute diff using this-year date; invalid dates approximate via day offset from Jan1
            try:
                ev_date=datetime.date(self.today.year,ev.month,ev.day)
            except:
                # approximate normalization
                try:
                    ev_date=datetime.date(self.today.year,1,1)+datetime.timedelta(days=(datetime.date(self.today.year,ev.month,1)-datetime.date(self.today.year,1,1)).days+(ev.day-1)) if 1<=ev.month<=12 else None
                except: ev_date=None
            if ev_date is None: continue
            diff=(ev_date-self.today).days
            if abs(diff)<=self.events_window:
                groups.setdefault(ev.category,[]).append((ev,diff))
                total+=1
        result=[]
        for cat in sorted(groups.keys()):
            items=sorted(groups[cat],key=lambda x:x[0].name)
            result.append((cat,items))
        return result,total
