    def move_calendar(self,dx,dy):
        cur=self.current_date; y,m,d=cur.year,cur.month,cur.day
        if dx==1:
            if d < days_in_month(y,m): self.set_date(datetime.date(y,m,d+1))
            elif m<12:
                nm=m+1; nd=min(self.month_memory[nm],days_in_month(y,nm)); self.set_date(datetime.date(y,nm,nd))
        elif dx==-1:
