            elif m>1:
                pm=m-1; nd=min(self.month_memory[pm],days_in_month(y,pm)); self.set_date(datetime.date(y,pm,nd))
        elif dy==1:
            if d+7 <= days_in_month(y,m): self.set_date(datetime.date(y,m,d+7))
            elif m<12:
                nm=m+1; nd=min(self.month_memory[nm],days_in_month(y,nm)); self.set_date(datetime.date(y,nm,nd))
        elif dy==-1:
            if d>7: self.set_date(datetime.date(y,m,d-7))
            elif m>1:
                pm=m-1; nd=min(self.month_memory[pm],days_in_month(y,pm)); self.set_date(datetime.date(y,pm,nd))
    def change_year(self,delta):
        new_year=self.display_year+delta
        if new_year<1 or new_year>9999: return
        self.display_year=new_year
        # current date changes to same month/day in new year, clamped
        m=self.current_date.month; d=self.current_date.day
        d=min(d,days_in_month(new_year,m))
        self.current_date=datetime.date(new_year,m,d)
        self.month_memory[m]=d
        self.sec_index=0; self.tag_index=0; self.preview_scroll=0
        # Note repository may have entries for new year already loaded; top updates
    # ------- menu navigation -------
    def move_menu(self,which,delta):
        if which=='sec':
            data=self.sections_data(); total=len(data)+1
            new=max(0,min(total-1,self.sec_index+delta))
            if new!=self.sec_index:
                self.sec_index=new; self.tag_index=0
        elif which=='tag':
            data=self.tags_data(); total=len(data)+1
            new=max(0,min(total-1,self.tag_index+delta))
            if new!=self.tag_index: self.tag_index=new
        elif which=='scratch':
            total=len(self.repo.scratchpads)+1 if self.repo else 1
            new=max(0,min(total-1,self.scratch_index+delta))
            if new!=self.scratch_index:
                self.scratch_index=new
                self.update_scratch_preview_mode()
